import "./quote.css";
import { RichValue } from "@/registry/p1/internal/rich";

export interface QuoteProps {
  quote: unknown;
  attribution: string;
  scale: "standard" | "display";
}

export function Quote({ quote, attribution, scale }: QuoteProps) {
  return (
    <div className="p1-quote p1-block" data-scale={scale}>
      <blockquote className="p1-quote__blockquote">
        <RichValue value={quote} className="p1-quote__text" />
        <cite className="p1-quote__cite">— {attribution}</cite>
      </blockquote>
    </div>
  );
}

"use client";

import type { ComponentConfig } from "@puckeditor/core";
import { richtextField } from "@pantheon-systems/puck-css/fields";
import { defineMeta } from '../define-meta';
import { Quote, type QuoteProps } from "./quote";
export type { QuoteProps };

export const QuoteBlock: ComponentConfig<QuoteProps> = {
  fields: {
    quote: richtextField,
    attribution: {
      type: "text" as const,
      ai: {
        instructions:
          "Name and optional title of the person being quoted. Example: 'Jane Smith, VP of Engineering'. 1–2 line max.",
      },
    },
    scale: {
      type: "radio" as const,
      options: [
        { label: "Standard", value: "standard" },
        { label: "Display", value: "display" },
      ],
    },
  },
  defaultProps: {
    quote:
      "The measure of intelligence is the ability to change. Adapt, evolve, and keep moving forward.",
    attribution: "Albert Einstein",
    scale: "standard",
  },
  render: Quote,
};

export const meta = defineMeta({
  title: 'Quote',
  description: 'Simple blockquote with rich-text quote and an attribution line in standard or display scale; use for inline quotations.',
  categories: ["content"],
  published: true,
  dependencies: ["@puckeditor/core","@pantheon-systems/puck-css"],
  registryDependencies: ["@p1/tokens","@p1/internal-rich"],
});

.p1-quote__blockquote {
  margin: 0;
  padding: 0;
}

.p1-quote__text {
  color: var(--p1-fg-default);
  text-wrap: balance;
}

.p1-quote[data-scale="standard"] .p1-quote__text {
  font-size: var(--p1-text-xl);
  line-height: var(--p1-leading-normal);
  font-style: italic;
}

@media (width >= 48rem) {
  .p1-quote[data-scale="standard"] .p1-quote__text {
    font-size: var(--p1-text-2xl);
  }
}

.p1-quote[data-scale="display"] .p1-quote__text {
  font-size: var(--p1-text-2xl);
  line-height: var(--p1-leading-tight);
  font-style: italic;
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
}

@media (width >= 48rem) {
  .p1-quote[data-scale="display"] .p1-quote__text {
    font-size: var(--p1-text-4xl);
  }
}

.p1-quote__cite {
  display: block;
  margin-block-start: var(--p1-space-md);
  font-size: var(--p1-text-sm);
  font-style: normal;
  color: var(--p1-fg-muted);
}

